import ast
import sys

# 读取脚本
with open('/tmp/xhs-topic-analyzer/scripts/claude_agent_runner.py', 'r') as f:
    code = f.read()

# 分析可能的阻塞点
issues = []

# 检查 1: subprocess.Popen 可能的输出缓冲问题
if 'subprocess.Popen' in code and 'stdout=subprocess.PIPE' in code:
    if 'text=True' in code:
        issues.append('⚠️  subprocess.Popen 使用 text=True 可能导致缓冲区阻塞')

# 检查 2: HTTP 请求超时设置
import re
requests_pattern = r'requests\.get\([^)]+\)'
requests_calls = re.findall(requests_pattern, code)
for call in requests_calls:
    if 'timeout' not in call:
        issues.append(f'⚠️  requests 调用缺少 timeout: {call[:60]}...')

# 检查 3: Anthropic SDK 调用
if 'client.messages.create' in code:
    lines = code.split('\n')
    in_api_call = False
    has_timeout = False
    for i, line in enumerate(lines):
        if 'client.messages.create' in line:
            in_api_call = True
        if in_api_call:
            if 'timeout' in line:
                has_timeout = True
                break
            if ')' in line and 'client.messages.create' not in line:
                break
    if not has_timeout:
        issues.append('⚠️  Anthropic API 调用没有显式设置 timeout 参数')

for issue in issues:
    print(issue)

if not issues:
    print('未发现明显的阻塞问题（静态分析）')
"
